<script lang="ts">
 import {SkeletonLoader} from '$lib/components/loaders';
 import {onMount,onDestroy} from 'svelte';import SamplePdfCanvas from './SamplePdfCanvas.svelte';import {uploadTo} from './api';
 let {file,id,name,downloadLabel='Download original',onclose}:{file?:File;id?:number;name:string;downloadLabel?:string;onclose:()=>void}=$props();
 let pdfBlob:Blob|null=$state(null);let dialog:HTMLDialogElement,kind=$state(''),url=$state(''),text=$state(''),error=$state(''),loading=$state(true);let alive=true;const controller=new AbortController();
 onMount(()=>{dialog.showModal();(async()=>{try{const ext=name.split('.').pop()?.toLowerCase()||'';let blob:Blob;
 if(file&&['docx','xlsx'].includes(ext)){const result=await uploadTo('/sample-files/preview',file);if(alive){text=result.text;kind='text'};return}
 if(file){blob=file}else{
  const response=await fetch('/api/sample-files/'+id+'?preview=1',{credentials:'same-origin',signal:controller.signal});
  if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.error||'Preview could not be loaded.')}
  blob=await response.blob();
 }
 if(['txt','csv','eml','dxf','plt','docx','xlsx'].includes(ext)){const body=await blob.slice(0,204800).text();if(alive){text=body;kind='text'}}else if(['pdf','png','jpg','jpeg'].includes(ext)){const type=ext==='pdf'?'application/pdf':ext==='png'?'image/png':'image/jpeg';const value=URL.createObjectURL(new Blob([blob],{type}));if(!alive){URL.revokeObjectURL(value);return}url=value;if(ext==='pdf')pdfBlob=blob;kind=ext==='pdf'?'pdf':'image'}else{throw Error('Preview is available for PDF, images, text, email, DOCX and XLSX. Download this file to view it.')}
 }catch(e){if(alive)error=(e as Error).message}finally{if(alive)loading=false}})()});
 function close(){if(!alive)return;alive=false;controller.abort();dialog.close();onclose()}
 onDestroy(()=>{alive=false;controller.abort();if(url)URL.revokeObjectURL(url);if(dialog?.open)dialog.close()});
</script>
<dialog bind:this={dialog} aria-label={'Preview: '+name} onclose={()=>{if(alive)onclose()}}><header><h2>{name}</h2><button type="button" onclick={close}>Close preview</button></header><div class="preview-body">{#if loading}<SkeletonLoader variant="detail" rows={7} columns={3} label="Loading file preview…"/>{:else if error}<p role="alert">{error}</p>{:else if kind==='text'}<pre>{text}</pre>{:else if kind==='image'}<img src={url} alt={name}/>{:else if kind==='pdf'}{#if pdfBlob}<SamplePdfCanvas blob={pdfBlob}/>{/if}{/if}</div><footer>{#if url}<a href={url} download={name}>{downloadLabel}</a>{:else if id}<a href={'/api/sample-files/'+id} download>{downloadLabel}</a>{/if}<span>Preview stays inside Euro Suits ERP.</span></footer></dialog>
<style>dialog{position:fixed;inset:16px;margin:auto;width:calc(100vw - 32px);height:calc(100dvh - 32px);max-width:1400px;max-height:none;padding:0;border:1px solid #b6c5ce;border-radius:10px;background:#fff;color:#111;box-shadow:0 16px 48px #10263633}dialog[open]{display:flex;flex-direction:column}dialog::backdrop{background:#102636aa}header{display:flex;align-items:center;justify-content:space-between;gap:16px;background:#132b40;color:white;padding:12px 20px}header h2{margin:0;font-size:18px;color:white!important;overflow-wrap:anywhere}button{min-height:44px;padding:8px 16px;color:#132b40;background:white;border:1px solid #c5d3da;border-radius:6px;cursor:pointer;flex-shrink:0;font:inherit}.preview-body{flex:1;min-height:0;overflow:auto;padding:16px}img{display:block;max-width:100%;max-height:100%;object-fit:contain;margin:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.6;font-family:inherit;color:#111}footer{display:flex;justify-content:space-between;gap:16px;padding:12px 20px;border-top:1px solid #c5d3da;font-size:13px}a{color:#087f83;font-weight:700}</style>
